// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        assertTrue(__invmut_c_Acc_balance(actor) == amount, "balance must equal deposit");
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
